/* ui/fade.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "../context.js";

export function install(P) {


  function formatFadeMs(ms) {
    const value = Math.max(0, Number(ms) || 0);
    if (value === 0) return P.pt("off");
    if (value < 1000) return `${value} ${P.pt("ms")}`;
    const seconds = value / 1000;
    return `${seconds % 1 === 0 ? seconds.toFixed(0) : seconds.toFixed(1)} ${P.pt("s")}`;
  }

  function drawFadeEnvelope() {
    document.querySelectorAll("#playerFadeCanvas").forEach((canvas) => {
      if (!(canvas instanceof HTMLCanvasElement)) return;
      const ctx = canvas.getContext("2d");
      if (!ctx) return;
      const w = canvas.width, h = canvas.height;
      const padX = 22, padTop = 18, padBottom = 14;
      const innerW = w - padX * 2, innerH = h - padTop - padBottom;
      const inMs = P.clamp(Number(P.state.fadeInMs) || 0, 0, P.CROSSFADE_MAX_MS);
      const outMs = P.clamp(Number(P.state.fadeOutMs) || 0, 0, P.CROSSFADE_MAX_MS);
      const bg = P.cssVar("--bg-elevated-2") || "#141414";
      const border = P.cssVar("--border") || "#2a2a2a";
      const text = P.cssVar("--text") || "#fff";
      const muted = P.cssVar("--muted") || "#a3a3a3";
      ctx.clearRect(0, 0, w, h);
      ctx.fillStyle = bg; ctx.fillRect(0, 0, w, h);
      ctx.strokeStyle = border; ctx.lineWidth = 1;
      ctx.strokeRect(padX, padTop, innerW, innerH);
      ctx.beginPath(); ctx.moveTo(padX, padTop + innerH); ctx.lineTo(padX + innerW, padTop + innerH); ctx.stroke();

      const xForMs = (ms) => padX + (P.clamp(ms, 0, P.CROSSFADE_MAX_MS) / P.CROSSFADE_MAX_MS) * innerW;
      const inX = xForMs(inMs);
      const outX = padX + innerW - (P.clamp(outMs, 0, P.CROSSFADE_MAX_MS) / P.CROSSFADE_MAX_MS) * innerW;
      const topY = padTop;
      const botY = padTop + innerH;
      const active = P.state.crossfade;

      // The whole ramp — not just the handle — shows whether a fade is live.
      // Disabled fades stay visible as a faint dashed guide.
      const drawRamp = (enabled, path) => {
        ctx.save();
        ctx.globalAlpha = active ? (enabled ? 1 : 0.3) : 0.18;
        path();
        ctx.fillStyle = "rgba(127,127,127,0.14)";
        ctx.fill();
        ctx.strokeStyle = enabled ? text : muted;
        ctx.lineWidth = enabled ? 2 : 1.2;
        ctx.setLineDash(enabled ? [] : [5, 5]);
        ctx.stroke();
        ctx.restore();
      };

      drawRamp(P.state.fadeInEnabled, () => {
        ctx.beginPath();
        ctx.moveTo(padX, botY);
        if (inMs <= 0) ctx.lineTo(padX, topY);
        else ctx.bezierCurveTo(padX + (inX - padX) * 0.25, botY, padX + (inX - padX) * 0.55, topY, inX, topY);
        ctx.lineTo(inX, botY);
        ctx.closePath();
      });
      drawRamp(P.state.fadeOutEnabled, () => {
        ctx.beginPath();
        ctx.moveTo(outX, topY);
        if (outMs <= 0) ctx.lineTo(padX + innerW, topY);
        else ctx.bezierCurveTo(outX + (padX + innerW - outX) * 0.45, topY, outX + (padX + innerW - outX) * 0.75, botY, padX + innerW, botY);
        ctx.lineTo(padX + innerW, topY);
        ctx.closePath();
      });

      const drawHandle = (x, type, enabled) => {
        const isActive = P.fadeDrag.type === type;
        const r = isActive ? 8 : 6;
        ctx.save();
        ctx.globalAlpha = active ? (enabled ? 1 : 0.45) : 0.25;
        const color = enabled ? text : muted;
        ctx.strokeStyle = color;
        ctx.lineWidth = 1.5;
        ctx.beginPath(); ctx.moveTo(x, topY); ctx.lineTo(x, botY); ctx.stroke();
        ctx.beginPath(); ctx.arc(x, topY, r, 0, Math.PI * 2);
        ctx.fillStyle = color; ctx.fill();
        ctx.strokeStyle = bg; ctx.lineWidth = 2; ctx.stroke();
        ctx.fillStyle = bg;
        ctx.fillRect(x - 3, topY - 2, 6, 4);
        ctx.restore();
      };
      drawHandle(inX, "in", P.state.fadeInEnabled);
      drawHandle(outX, "out", P.state.fadeOutEnabled);
      if (!P.state.fadeInEnabled || !P.state.fadeOutEnabled) {
        ctx.save();
        ctx.fillStyle = muted;
        ctx.font = "10px sans-serif";
        ctx.textAlign = "center";
        if (!P.state.fadeInEnabled) ctx.fillText(P.pt("off"), padX + (inX - padX) / 2, botY - 8);
        if (!P.state.fadeOutEnabled) ctx.fillText(P.pt("off"), (outX + padX + innerW) / 2, botY - 8);
        ctx.restore();
      }
    });
  }

  function bindFadeCanvasInteractions() {
    document.querySelectorAll("#playerFadeCanvas").forEach((canvas) => {
      if (!(canvas instanceof HTMLCanvasElement) || canvas.dataset.fadeBound === "1") return;
      canvas.dataset.fadeBound = "1";
      canvas.style.touchAction = "none";
      const toMs = (ev) => {
        const rect = canvas.getBoundingClientRect();
        const x = ((ev.clientX - rect.left) / rect.width) * canvas.width;
        const padX = 22, innerW = canvas.width - padX * 2;
        return P.clamp(Math.round((P.clamp(x - padX, 0, innerW) / innerW) * P.CROSSFADE_MAX_MS / 50) * 50, 0, P.CROSSFADE_MAX_MS);
      };
      const pick = (ev) => {
        const rect = canvas.getBoundingClientRect();
        const x = ((ev.clientX - rect.left) / rect.width) * canvas.width;
        const padX = 22, innerW = canvas.width - padX * 2;
        const inX = padX + (P.clamp(P.state.fadeInMs, 0, P.CROSSFADE_MAX_MS) / P.CROSSFADE_MAX_MS) * innerW;
        const outX = padX + innerW - (P.clamp(P.state.fadeOutMs, 0, P.CROSSFADE_MAX_MS) / P.CROSSFADE_MAX_MS) * innerW;
        const inDist = Math.abs(x - inX);
        const outDist = Math.abs(x - outX);
        if (Math.min(inDist, outDist) > 28) return inDist <= outDist ? "in" : "out";
        return inDist <= outDist ? "in" : "out";
      };
      const rawForType = (type, ev) => {
        const ms = toMs(ev);
        return type === "out" ? P.CROSSFADE_MAX_MS - ms : ms;
      };
      const applyDrag = (ev) => {
        const raw = rawForType(P.fadeDrag.type, ev);
        const offset = P.fadeDrag.type === "in" ? P.fadeDrag.offsetIn : P.fadeDrag.offsetOut;
        const ms = P.clamp(raw + offset, 0, P.CROSSFADE_MAX_MS);
        if (P.fadeDrag.type === "in") P.state.fadeInMs = ms; else P.state.fadeOutMs = ms;
        P.syncFadeVisual(); P.syncSettingsUI(); P.saveState(); P.notify("settings");
      };
      canvas.addEventListener("pointerdown", (ev) => {
        if (!P.state.crossfade) return;
        P.fadeDrag.type = pick(ev);
        P.fadeDrag.pointerId = ev.pointerId;
        // Keep the grab point on the handle. Without this offset a click
        // anywhere on the canvas snapped the chosen point to the cursor.
        const raw = rawForType(P.fadeDrag.type, ev);
        P.fadeDrag.offsetIn = P.fadeDrag.type === "in" ? P.clamp(P.state.fadeInMs, 0, P.CROSSFADE_MAX_MS) - raw : 0;
        P.fadeDrag.offsetOut = P.fadeDrag.type === "out" ? P.clamp(P.state.fadeOutMs, 0, P.CROSSFADE_MAX_MS) - raw : 0;
        canvas.setPointerCapture?.(ev.pointerId);
        applyDrag(ev);
      });
      canvas.addEventListener("pointermove", (ev) => {
        if (P.fadeDrag.pointerId !== ev.pointerId || !P.fadeDrag.type) return;
        applyDrag(ev);
      });
      const end = (ev) => {
        if (P.fadeDrag.pointerId !== ev.pointerId) return;
        P.fadeDrag.type = null; P.fadeDrag.pointerId = null;
        P.fadeDrag.offsetIn = 0; P.fadeDrag.offsetOut = 0;
        P.drawFadeEnvelope();
      };
      canvas.addEventListener("pointerup", end);
      canvas.addEventListener("pointercancel", end);
    });
  }

  function syncFadeVisual() {
    // Visual order follows the setting order: fade-in first (left), fade-out
    // last (right). The actual crossfade still overlaps both curves in time.
    const inMs = P.clamp(Number(P.state.fadeInMs) || 0, 0, P.CROSSFADE_MAX_MS);
    const outMs = P.clamp(Number(P.state.fadeOutMs) || 0, 0, P.CROSSFADE_MAX_MS);
    document.querySelectorAll("#playerFadeSummary").forEach((el) => { el.textContent = `${P.formatFadeMs(inMs)} / ${P.formatFadeMs(outMs)}`; });
    document.querySelectorAll("#playerFadeOutValue").forEach((el) => { el.textContent = P.formatFadeMs(outMs); });
    document.querySelectorAll("#playerFadeInValue").forEach((el) => { el.textContent = P.formatFadeMs(inMs); });
    P.bindFadeCanvasInteractions();
    P.drawFadeEnvelope();

    document.querySelectorAll("[data-fade-setting]").forEach((el) => {
      el.classList.toggle("is-disabled", !P.state.crossfade);
      el.querySelectorAll("input[data-player-setting='fadeInMs'], input[data-player-setting='fadeOutMs']").forEach((input) => {
        input.disabled = !P.state.crossfade;
      });
    });
    document.querySelectorAll("[data-fade-control]").forEach((el) => {
      const name = el.dataset.fadeControl === "in" ? "fadeInEnabled" : "fadeOutEnabled";
      el.classList.toggle("is-off", !P.state.crossfade || !P.state[name]);
      const range = el.querySelector("input[type='range']");
      if (range) range.disabled = !P.state.crossfade || !P.state[name];
    });
  }

  function syncIntroVisual() {
    document.querySelectorAll("#playerSilenceDbValue").forEach((el) => {
      el.textContent = `${P.state.silenceDb} ${P.pt("db")}`;
    });
    document.querySelectorAll("#playerIntroMaxValue").forEach((el) => {
      el.textContent = `${P.state.introMaxSec} ${P.pt("s")}`;
    });
    document.querySelectorAll("[data-intro-setting]").forEach((el) => {
      el.classList.toggle("is-disabled", !P.state.skipIntro);
      el.querySelectorAll("input").forEach((input) => { input.disabled = !P.state.skipIntro; });
    });
  }

  function syncPlaybackVisual() {
    document.querySelectorAll("#playerPlaybackRateValue").forEach((el) => {
      const v = P.clampPlaybackRate(P.state.playbackRate);
      el.textContent = `${Number.isInteger(v) ? v.toFixed(0) : v.toFixed(2).replace(/0+$/, "").replace(/\.$/, "")}x`;
    });
  }
  Object.assign(P, { formatFadeMs, drawFadeEnvelope, bindFadeCanvasInteractions, syncFadeVisual, syncIntroVisual, syncPlaybackVisual });
}
